-- ============================================
-- 回血神符 / 切割系统共享世界数据
-- 1. 新增 200 种分级升级材料：
--    994001-994100 神符碎片1-100
--    994101-994200 切割神石1-100
-- 2. 新增需求模板 930001-930200
-- 3. 新增 200 个野外静态 Boss：395001-395100 / 395101-395200
-- ============================================

DROP TEMPORARY TABLE IF EXISTS `_tmp_worldboss395_levels`;
CREATE TEMPORARY TABLE `_tmp_worldboss395_levels` (
  `lvl` int unsigned NOT NULL,
  PRIMARY KEY (`lvl`)
) ENGINE=MEMORY;


DELETE FROM `creature` WHERE `id1` BETWEEN 395001 AND 395200;
DELETE FROM `creature_loot_template` WHERE `Entry` BETWEEN 395001 AND 395200;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 395001 AND 395200;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 395001 AND 395200;
DELETE FROM `_模板_需求` WHERE `id` BETWEEN 930001 AND 930200;
DELETE FROM `item_template` WHERE `entry` BETWEEN 994001 AND 994200;

SELECT
  994000 + `lvl`,
  7,
  5,
  -1,
  CONCAT('神符碎片', `lvl`),
  46711,
  1,
  0,
  0,
  1,
  0,
  0,
  0,
  32767,
  -1,
  80,
  999999999,
  CONCAT('回血神符', `lvl`, '级升级材料'),
  7,
  0,
  12340
FROM `_tmp_worldboss395_levels`;

SELECT
  994100 + `lvl`,
  7,
  7,
  -1,
  CONCAT('切割神石', `lvl`),
  52705,
  1,
  0,
  0,
  1,
  0,
  0,
  0,
  -1,
  -1,
  80,
  999999999,
  CONCAT('切割系统', `lvl`, '级升级材料'),
  1,
  1024,
  12340
FROM `_tmp_worldboss395_levels`;

SELECT
  CONCAT('回血神符升级-', LPAD(`lvl`, 3, '0')),
  930000 + `lvl`,
  1,
  CONCAT(994000 + `lvl`, ' 1'),
  CONCAT('消耗神符碎片', `lvl`, ' x1 激活回生神符·', LPAD(`lvl`, 3, '0'))
FROM `_tmp_worldboss395_levels`;

SELECT
  CONCAT('切割系统升级-', LPAD(`lvl`, 3, '0')),
  930100 + `lvl`,
  1,
  CONCAT(994100 + `lvl`, ' 1'),
  CONCAT('消耗切割神石', `lvl`, ' x1 升级到切割 ', `lvl`, ' 级')
FROM `_tmp_worldboss395_levels`;


SET @boss_guid_base := (SELECT COALESCE(MAX(`guid`), 0) FROM `creature`);


-- 当前世界Boss不使用武器模板，避免 equipment_id=1 触发 creature_equip_template 缺失告警
UPDATE `creature`
SET `equipment_id` = 0
WHERE `id1` BETWEEN 395001 AND 395200;

SELECT
  395000 + `lvl`,
  994000 + `lvl`,
  0,
  100,
  0,
  1,
  0,
  1,
  1,
  CONCAT('回血Boss #', LPAD(`lvl`, 3, '0'))
FROM `_tmp_worldboss395_levels`;

SELECT
  395100 + `lvl`,
  994100 + `lvl`,
  0,
  100,
  0,
  1,
  0,
  1,
  1,
  CONCAT('切割Boss #', LPAD(`lvl`, 3, '0'))
FROM `_tmp_worldboss395_levels`;

DROP TEMPORARY TABLE IF EXISTS `_tmp_worldboss395_levels`;
-- ============================================
-- 世界Boss外观强化
-- 每5个Boss固定一套模型，统一放大到 5 倍
-- 01组 末日行者         21435
-- 02组 末日领主卡扎克   17887
-- 03组 屠龙者格鲁尔     18698
-- 04组 玛瑟里顿         18527
-- 05组 伊利丹·怒风      21135
-- 06组 伊利丹恶魔形态   21322
-- 07组 阿克蒙德         20939
-- 08组 克苏恩           15787
-- 09组 阿努布雷坎       15931
-- 10组 克尔苏加德       15945
-- 11组 高阶督军纳因图斯 21174
-- 12组 基尔加丹         23200
-- 13组 布鲁塔卢斯       22711
-- 14组 菲米丝           22838
-- 15组 玛里苟斯         26752
-- 16组 萨塔里奥         27035
-- 17组 科隆加恩         28638
-- 18组 玛洛加尔领主     31119
-- 19组 巫妖王           30721
-- 20组 阿努巴拉克       29268
--
-- 强度重调
-- 1. 全部提升为世界Boss rank=3
-- 2. 回血Boss更偏肉，切割Boss更偏输出
-- 3. 按每5个Boss一档递增强度
-- 4. 当前版本在原始强度基础上，血量与伤害整体提高 6 倍
-- ============================================

UPDATE `creature_template`
SET
  `scale` = 5.0,
  `faction` = 14,
  `detection_range` = 60,
  `rank` = 3,
  `HealthModifier` = CASE
    WHEN `entry` BETWEEN 395001 AND 395100 THEN (60 + (((`entry` - 395001) DIV 5) + 1) * 12) * 6
    WHEN `entry` BETWEEN 395101 AND 395200 THEN (48 + (((`entry` - 395101) DIV 5) + 1) * 10) * 6
    ELSE `HealthModifier`
  END,
  `DamageModifier` = CASE
    WHEN `entry` BETWEEN 395001 AND 395100 THEN (4.0 + (((( `entry` - 395001) DIV 5) + 1) * 0.45)) * 6
    WHEN `entry` BETWEEN 395101 AND 395200 THEN (4.8 + (((( `entry` - 395101) DIV 5) + 1) * 0.50)) * 6
    ELSE `DamageModifier`
  END,
  `ArmorModifier` = CASE
    WHEN `entry` BETWEEN 395001 AND 395100 THEN 2.5 + (((( `entry` - 395001) DIV 5) + 1) * 0.15)
    WHEN `entry` BETWEEN 395101 AND 395200 THEN 2.2 + (((( `entry` - 395101) DIV 5) + 1) * 0.14)
    ELSE `ArmorModifier`
  END
WHERE `entry` BETWEEN 395001 AND 395200;

UPDATE `creature_template_model`
SET
  `CreatureDisplayID` = CASE
    WHEN (`CreatureID` BETWEEN 395001 AND 395005) OR (`CreatureID` BETWEEN 395101 AND 395105) THEN 21435
    WHEN (`CreatureID` BETWEEN 395006 AND 395010) OR (`CreatureID` BETWEEN 395106 AND 395110) THEN 17887
    WHEN (`CreatureID` BETWEEN 395011 AND 395015) OR (`CreatureID` BETWEEN 395111 AND 395115) THEN 18698
    WHEN (`CreatureID` BETWEEN 395016 AND 395020) OR (`CreatureID` BETWEEN 395116 AND 395120) THEN 18527
    WHEN (`CreatureID` BETWEEN 395021 AND 395025) OR (`CreatureID` BETWEEN 395121 AND 395125) THEN 21135
    WHEN (`CreatureID` BETWEEN 395026 AND 395030) OR (`CreatureID` BETWEEN 395126 AND 395130) THEN 21322
    WHEN (`CreatureID` BETWEEN 395031 AND 395035) OR (`CreatureID` BETWEEN 395131 AND 395135) THEN 20939
    WHEN (`CreatureID` BETWEEN 395036 AND 395040) OR (`CreatureID` BETWEEN 395136 AND 395140) THEN 15787
    WHEN (`CreatureID` BETWEEN 395041 AND 395045) OR (`CreatureID` BETWEEN 395141 AND 395145) THEN 15931
    WHEN (`CreatureID` BETWEEN 395046 AND 395050) OR (`CreatureID` BETWEEN 395146 AND 395150) THEN 15945
    WHEN (`CreatureID` BETWEEN 395051 AND 395055) OR (`CreatureID` BETWEEN 395151 AND 395155) THEN 21174
    WHEN (`CreatureID` BETWEEN 395056 AND 395060) OR (`CreatureID` BETWEEN 395156 AND 395160) THEN 23200
    WHEN (`CreatureID` BETWEEN 395061 AND 395065) OR (`CreatureID` BETWEEN 395161 AND 395165) THEN 22711
    WHEN (`CreatureID` BETWEEN 395066 AND 395070) OR (`CreatureID` BETWEEN 395166 AND 395170) THEN 22838
    WHEN (`CreatureID` BETWEEN 395071 AND 395075) OR (`CreatureID` BETWEEN 395171 AND 395175) THEN 26752
    WHEN (`CreatureID` BETWEEN 395076 AND 395080) OR (`CreatureID` BETWEEN 395176 AND 395180) THEN 27035
    WHEN (`CreatureID` BETWEEN 395081 AND 395085) OR (`CreatureID` BETWEEN 395181 AND 395185) THEN 28638
    WHEN (`CreatureID` BETWEEN 395086 AND 395090) OR (`CreatureID` BETWEEN 395186 AND 395190) THEN 31119
    WHEN (`CreatureID` BETWEEN 395091 AND 395095) OR (`CreatureID` BETWEEN 395191 AND 395195) THEN 30721
    WHEN (`CreatureID` BETWEEN 395096 AND 395100) OR (`CreatureID` BETWEEN 395196 AND 395200) THEN 29268
    ELSE `CreatureDisplayID`
  END,
  `DisplayScale` = 1.0
WHERE `CreatureID` BETWEEN 395001 AND 395200;
